sksl:
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 toLayer;
uniform float3x3 fromLayer;
uniform float falloff;
uniform float2 pin1;
uniform float2 rest1;
uniform float2 pin2;
uniform float2 rest2;
uniform float2 pin3;
uniform float2 rest3;
uniform float2 pin4;
uniform float2 rest4;
uniform float2 pin5;
uniform float2 rest5;
uniform float2 pin6;
uniform float2 rest6;
uniform float2 pin7;
uniform float2 rest7;
uniform float2 pin8;
uniform float2 rest8;
uniform float2 pin9;
uniform float2 rest9;
uniform float2 pin10;
uniform float2 rest10;
uniform float2 pin11;
uniform float2 rest11;
uniform float2 pin12;
uniform float2 rest12;
uniform float2 pin13;
uniform float2 rest13;
uniform float2 pin14;
uniform float2 rest14;
uniform float2 pin15;
uniform float2 rest15;
uniform float2 pin16;
uniform float2 rest16;

half4 at(float2 p) {
    float3 g = fromLayer * float3(p, 1.0);
    return image.eval(g.xy / g.z);
}

void accumPin(float2 p, float2 cur, float2 rst, float power, inout float2 disp, inout float totalWeight) {
    if (rst.x > -90000.0 && cur.x > -90000.0) {
        float2 diff = p - cur;
        float distSq = dot(diff, diff);
        float w = 1.0 / (pow(distSq + 16.0, power) + 0.0001);
        disp += (cur - rst) * w;
        totalWeight += w;
    }
}

half4 main(float2 coord) {
    float3 h = toLayer * float3(coord, 1.0);
    float2 lp = h.xy / h.z;
    float power = 0.5 + 0.5 / (1.0 + clamp(falloff, 0.1, 4.0));
    float totalWeight = 0.0;
    float2 disp = float2(0.0);

    accumPin(lp, pin1, rest1, power, disp, totalWeight);
    accumPin(lp, pin2, rest2, power, disp, totalWeight);
    accumPin(lp, pin3, rest3, power, disp, totalWeight);
    accumPin(lp, pin4, rest4, power, disp, totalWeight);
    accumPin(lp, pin5, rest5, power, disp, totalWeight);
    accumPin(lp, pin6, rest6, power, disp, totalWeight);
    accumPin(lp, pin7, rest7, power, disp, totalWeight);
    accumPin(lp, pin8, rest8, power, disp, totalWeight);
    accumPin(lp, pin9, rest9, power, disp, totalWeight);
    accumPin(lp, pin10, rest10, power, disp, totalWeight);
    accumPin(lp, pin11, rest11, power, disp, totalWeight);
    accumPin(lp, pin12, rest12, power, disp, totalWeight);
    accumPin(lp, pin13, rest13, power, disp, totalWeight);
    accumPin(lp, pin14, rest14, power, disp, totalWeight);
    accumPin(lp, pin15, rest15, power, disp, totalWeight);
    accumPin(lp, pin16, rest16, power, disp, totalWeight);

    if (totalWeight <= 0.00001) {
        return image.eval(coord);
    }
    float2 lp_src = lp - disp / totalWeight;
    return at(lp_src);
}
